"""Auto-generate docs/DATA_DICTIONARY.md from a cleaned frame."""

from __future__ import annotations

from pathlib import Path

import polars as pl

from eci.data.schema_contract import DTYPE_TABLE


def build_data_dictionary(
    df: pl.DataFrame,
    dest: Path,
    provenance: dict,
    stats: dict | None = None,
) -> None:
    height = df.height
    lines = [
        "# Data dictionary",
        "",
        "Auto-generated by `scripts/run_audit.py`. Regenerate with `make audit`.",
        "",
        "## Provenance",
        "",
    ]
    for key, value in provenance.items():
        lines.append(f"- {key}: `{value}`")
    lines.extend(
        [
            "",
            "## Columns",
            "",
            "| column | dtype | unit | null_pct | description |",
            "|---|---|---|---:|---|",
        ]
    )
    for column in df.columns:
        meta = DTYPE_TABLE.get(column, {})
        nulls = df.get_column(column).null_count()
        null_pct = 0.0 if height == 0 else 100.0 * nulls / height
        dtype = meta.get("dtype", str(df.schema[column]))
        unit = meta.get("unit", "")
        description = meta.get("description", "").replace("|", "/")
        lines.append(f"| `{column}` | {dtype} | {unit} | {null_pct:.2f} | {description} |")

    lines.extend(
        [
            "",
            "## Measured on this run",
            "",
        ]
    )
    if stats:
        lines.append(f"- sessions: {stats.get('n')}")
        lines.append(
            f"- f_clock_skew: {stats.get('clock_skew_count')} ({stats.get('clock_skew_rate', 0):.2%})"
        )
        lines.append(
            "- dwell > 24h: "
            f"{stats.get('long_dwell_24h_count')} ({stats.get('long_dwell_24h_rate', 0):.2%})"
        )
        lines.append(
            "- f_long_dwell > 48h: "
            f"{stats.get('long_dwell_flag_count')} ({stats.get('long_dwell_flag_rate', 0):.2%})"
        )
        lines.append(
            "- userID missing: "
            f"{stats.get('user_id_missing_count')} ({stats.get('user_id_missing_rate', 0):.2%})"
        )
        lines.append(
            "- multi-input (more than one event, among sessions that submitted userInputs): "
            f"{stats.get('multi_input_count')} / {stats.get('multi_input_with_inputs')} "
            f"({stats.get('multi_input_rate', 0):.2%})"
        )
        lines.append(f"- kWh == 0: {stats.get('kwh_zero_count')} ({stats.get('kwh_zero_rate', 0):.2%})")
        lines.append(f"- arrival peak local hour: {stats.get('peak_hour')}")
    lines.extend(
        [
            "",
            "## TODO verify before any cost or capacity claim",
            "",
            "- SCE EV-4 (March 2019) clock windows and USD/kWh are placeholders in `configs/tariff_sce_ev4.yaml`.",
            "- EVN Decision 963/2026 VND/kWh are placeholders in `configs/tariff_evn_2026.yaml`.",
            "- The EVN peak window 17:30–22:30 Monday–Saturday is the brief, not a transcribed tariff table.",
            "- Per-EVSE amp split. `evse_power_default_kw: 6.7` is a placeholder.",
            "- NOAA/IEM ASOS weather license before redistribution.",
            "",
        ]
    )
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text("\n".join(lines), encoding="utf-8")
    _restore_measured_hazards(dest)


def _restore_measured_hazards(dest: Path) -> None:
    """Keep the day-2 hazard section when `make audit` regenerates this file."""
    import csv

    from eci.config import REPO_ROOT

    csv_path = REPO_ROOT / "results" / "hazard_metrics.csv"
    if not csv_path.exists():
        return
    with csv_path.open(encoding="utf-8", newline="") as handle:
        rows = list(csv.DictReader(handle))
    for row in rows:
        raw = row.get("value")
        row["value"] = None if raw in (None, "", "None") else float(raw)
        row["n"] = int(row["n"])
        row["low_confidence"] = str(row["low_confidence"]).lower() == "true"
    from eci.data.measures import upsert_hazard_section

    upsert_hazard_section(dest, rows)
